let audioURLs = []
const lesson_id = $('prepare').first().json._id

for (let i = 0; i < $('SlideContentGenerator').first().json.transcripts.length; i++) {
  const url =`https://capstone-ai-education.s3.amazonaws.com/${lesson_id}/audio/audio_${i + 1}.wav`
  audioURLs.push(url)
}

return { 
  audioURLs, 
  "lessonId": lesson_id,
  audioStatus: "GENERATED"
};

// 1. Get the raw string from the previous node
let rawString = $input.item.json.data;

// 2. Un-escape the first layer if n8n double-wrapped it in quotes
if (typeof rawString === 'string' && rawString.startsWith('"') && rawString.endsWith('"')) {
  try { 
    rawString = JSON.parse(rawString); 
  } catch (e) {
    // silently continue if it fails
  }
}

// 3. Strip out any Markdown backticks and 'json' labels
let cleanText = rawString.replace(/```json/gi, '').replace(/```/gi, '').trim();

let parsedData;

// 4. Parse the clean text
try {
  parsedData = JSON.parse(cleanText);

  // 5. The Magic Fix: If it is STILL a string after parsing, parse it one more time!
  if (typeof parsedData === 'string') {
    parsedData = JSON.parse(parsedData);
  }
} catch (error) {
  return [{ json: { error: "Failed to parse JSON completely", raw: cleanText } }];
}

// 6. Return the actual array of objects in n8n's required format
return {
    sections: parsedData 
  };

